{#- Code generated by packages/kit-compose/src/build.ts from src/map.ts + variants/. DO NOT EDIT.
    Breadcrumb: Box nav > ol > li, Link or Text span. Props (p): Items [{label, href, current, disabled}], AriaLabel, Class, Attrs. -#}
{%- set lis %}{% for it in p['Items'] or [] %}{% set c = compose_join(['text-sm', 'font-medium' if it['current'] else ('text-muted-foreground' if it['disabled'] else 'text-primary underline-offset-4 hover:underline')]) %}{% set a = {'aria-current': 'page'} if it['current'] else {} %}{% set inner %}{% if it['href'] and not it['disabled'] %}{% with p = {'Href': it['href'], 'Class': c, 'Attrs': a}, children = it['label']|e %}{% include 'ui/link/link.html.j2' %}{% endwith %}{% else %}{% with p = {'Tag': 'span', 'Class': c, 'Attrs': a}, children = it['label']|e %}{% include 'ui/text/text.html.j2' %}{% endwith %}{% endif %}{% endset %}{% with p = {'Tag': 'li', 'Class': 'inline-flex items-center'}, children = inner %}{% include 'ui/box/box.html.j2' %}{% endwith %}{% endfor %}{% endset %}
{%- set ol %}{% with p = {'Tag': 'ol', 'Class': 'flex flex-wrap items-center gap-2'}, children = lis %}{% include 'ui/box/box.html.j2' %}{% endwith %}{% endset %}
{%- set a = {'aria-label': p['AriaLabel'] or 'Breadcrumb'} %}{%- set _ = a.update(p['Attrs'] or {}) %}
{%- with p = {'Tag': 'nav', 'Class': compose_join(['text-sm', p['Class']]), 'Attrs': a}, children = ol %}{% include 'ui/box/box.html.j2' %}{% endwith %}
